  [16333] = { "$D1の間、敵の筋力を$N1、スタミナを$N2低下させます。", "筋力が$N1低下しています。\nスタミナが$N2低下しています。", 0x75f48aac, 0xa274e4eb, "uu" },
  [16336] = { "敵に$D1の間呪いをかけ、定期的に悪意ある幽霊に取り憑かれるようにします。", "取り憑かれています……", 0x9d503b40, 0x448299b4, "uu" },
  [16339] = { "シャーマンの武器に炎を宿します。命中するたびに、武器の速度に応じて$N1の追加Fireダメージを与えます。遅い武器ほど一振りあたりのFireダメージが大きくなります。メインハンドに付与すると、Flametongue Totemから自身が受ける恩恵はすべて無効になります。効果時間は60分です。", nil, 0x519a68fb, nil, "um" },
  [16340] = { "術者の前方の円錐範囲にいる敵にFrostダメージを与え、マナを奪い、$D1の間、移動速度を低下させます。", "移動速度が低下しています。", 0x03102da3, 0xeadcb05a, "uu" },
  [16341] = { "シャーマンの武器に炎を宿します。命中するたびに、武器の速度に応じて$N1の追加Fireダメージを与えます。遅い武器ほど一振りあたりのFireダメージが大きくなります。メインハンドに付与すると、Flametongue Totemから自身が受ける恩恵はすべて無効になります。効果時間は60分です。", nil, 0x94b40ea5, nil, "um" },
  [16342] = { "シャーマンの武器に炎を宿します。命中するたびに、武器の速度に応じて$N1の追加Fireダメージを与えます。遅い武器ほど一振りあたりのFireダメージが大きくなります。メインハンドに付与すると、Flametongue Totemから自身が受ける恩恵はすべて無効になります。効果時間は60分です。", nil, 0x3fa3f126, nil, "um" },
  [16350] = { "氷の衝撃波を放ち、術者の前方の円錐範囲にいる敵をスタンさせてダメージを与え、さらに$D2の間、$D1ごとに追加のFrostダメージを与えます。", "スタンしています。\n$D1ごとにFrostダメージを受けています。", 0x7ff3a8d2, 0x80cdb519, "uu" },
