  [16359] = { "術者の前方の円錐範囲にいる敵に酸の息を吐きかけ、アーマーを下げ、$D2の間、$D1ごとにNatureダメージを与えます。", "アーマーが低下しています。\n$D1ごとにNatureダメージを受けています。", 0x2108c165, 0x06dba88c, "uu" },
