  [16366] = { nil, "与える物理ダメージが$N1増加しています。", nil, 0x422f867d, "mu" },
  [16367] = { "傷ついた味方に癒しのエネルギーを注ぎ込み、エネルギーは近くにいる別の味方へ広がります。この呪文は最大$N1体の対象に作用しますが、次の対象に移るたびに回復量が50%減少します。", nil, 0xaf264114, nil, "um" },
