  [16430] = { "敵の魂を吸い取ります。$D1ごとに体力を$N1、$D2ごとにマナを$N3奪い、術者に移します。効果時間は$D3です。", "$D1ごとに体力を$N1吸い取られています。\n$D2ごとにマナを$N3吸い取られています。", 0xf952e343, 0x012514c3, "uu" },
  [16431] = { "術者を骨の鎧で覆い、$D1の間、$N1のダメージを吸収します。鎧が持ちこたえている間、Physical攻撃で詠唱を妨害されません。", "ダメージは骨の鎧に吸収されます。", 0x94214c39, 0xc6778006, "uu" },
