  [16457] = { "Slimが戦闘に入ると、Slim's Friendsの一人を召喚して助けさせます。", nil, 0x78e05912, nil, "um" },
  [16458] = { "敵の移動速度を$N1%低下させ、その敵が与えるすべての物理ダメージと魔法のダメージを$N2軽減します。効果時間は$D1です。", "移動速度が$N1%低下しています。\n与える物理ダメージと魔法ダメージが$N2減少しています。", 0x942dc1e7, 0x261ea1c5, "uu" },
