  [16462] = { "Parry率を$N1%上昇させます。", nil, 0x8ac819e9, nil, "um" },
  [16468] = { "近くの敵を毒に冒します。知識のある医療の専門家が血中から毒を完全に取り除くまで、毒に冒された者とその近くの仲間は定期的に動けなくなります。", "近くの味方と共に移動不能になることがあります。毒が解呪されるか、術者の毒が搾り取られるまで続きます。", 0x65095455, 0xb7c45e58, "uu" },
  [16469] = { "$D1の間、対象を動けなくします。", nil, 0x0c9c13b6, nil, "um" },
  [16470] = { "$D1の間アーマーを$N1上昇させますが、効果中は呪文の詠唱も攻撃もできません。", "アーマーが$N1上昇していますが、攻撃も呪文の詠唱もできません。", 0xefd12024, 0x58d4d8bc, "uu" },
  [16472] = { "対象の毒の効果を$N1個取り除きます。", nil, 0xa536de69, nil, "um" },
